    deepExplanation: "Step 1 — Maintain a start index.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction combinations(\n  n: number,\n  k: number,\n): number[][] {\n  const result: number[][] = [];\n  const current: number[] = [];\n\n  function backtrack(start: number): void {\n    if (current.length === k) {\n      result.push([...current]);\n      return;\n    }\n\n    const remainingNeeded = k - current.length;\n\n    for (\n      let value = start;\n      value <= n - remainingNeeded + 1;\n      value++\n    ) {\n      current.push(value);\n      backtrack(value + 1);\n      current.pop();\n    }\n  }\n\n  if (k < 0 || k > n) return [];\n  backtrack(1);\n\n  return result;\n}\n```\n\nStep 2 — WITH BUILT-IN:\n```ts\nfunction combinationsUsingArray(\n  values: readonly number[],\n  k: number,\n): number[][] {\n  const result: number[][] = [];\n\n  function build(start: number, current: number[]): void {\n    if (current.length === k) {\n      result.push([...current]);\n      return;\n    }\n\n    for (let i = start; i < values.length; i++) {\n      build(i + 1, [...current, values[i]!]);\n    }\n  }\n\n  if (k < 0 || k > values.length) return [];\n  build(0, []);\n  return result;\n}\n```\n\nStep 3 — Example:\nC(4,2) → [1,2], [1,3], [1,4], [2,3], [2,4], [3,4].\n\nStep 4 — Complexity:\nThere are C(n,k) outputs; returning them costs at least O(k·C(n,k)).",
