    expectedAnswer: "Combination Sum uses backtracking to choose candidate values repeatedly until the target is reached. After sorting candidates, stop exploring when the next candidate is already larger than the remaining target.",
    deepExplanation: "Step 1 — Sort and backtrack with reusable indexes.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction combinationSum(\n  candidates: readonly number[],\n  target: number,\n): number[][] {\n  const values = [...candidates].sort((a, b) => a - b);\n  const result: number[][] = [];\n  const current: number[] = [];\n\n  function backtrack(start: number, remaining: number): void {\n    if (remaining === 0) {\n      result.push([...current]);\n      return;\n    }\n\n    for (let i = start; i < values.length; i++) {\n      const value = values[i]!;\n\n      if (value > remaining) break;\n\n      current.push(value);\n      backtrack(i, remaining - value);\n      current.pop();\n    }\n  }\n\n  if (target < 0) return [];\n  backtrack(0, target);\n\n  return result;\n}\n```\n\nStep 2 — WITH BUILT-IN:\n```ts\nfunction combinationSumUsingFilter(\n  candidates: readonly number[],\n  target: number,\n): number[][] {\n  const values = [...new Set(candidates)].sort((a, b) => a - b);\n  const result: number[][] = [];\n\n  function dfs(start: number, remaining: number, path: number[]): void {\n    if (remaining === 0) {\n      result.push(path);\n      return;\n    }\n\n    values\n      .slice(start)\n      .filter((value) => value <= remaining)\n      .forEach((value, offset) => {\n        dfs(start + offset, remaining - value, [...path, value]);\n      });\n  }\n\n  dfs(0, target, []);\n  return result;\n}\n```\n\nStep 3 — Example:\ncandidates [2,3,6,7], target 7\n→ [2,2,3], [7].\n\nStep 4 — Complexity:\nThe search is exponential in the worst case; exact complexity depends on target/candidates. Sorting adds O(m log m).",
